    input_rev = grid[::-1]

    # Build output as 3x2 blocks of 6x15
    output = []
    for br in range(3):
        for bc in range(2):
            if br == 0:
                if bc == 0:
                    block = rot180
                else:
                    block = input_rev
            elif br == 1:
                if bc == 0:
                    block = rot180[::-1]
                else:
                    block = grid
            else:
                if bc == 0:
                    block = rot180
                else:
                    block = input_rev

            output.extend(block)

    return output

